/**
 * Shared pieces of the workspace pages' scenes: a layer that places the app's
 * `position: fixed` surfaces (portaled dropdowns, the resize outline, modals)
 * against the scene's window the way the app places them against its own
 * window, the measurement those surfaces anchor to, and the small app
 * components they show (src/ui/LiveSessionIcon.tsx, src/ui/DeviceIcon.tsx).
 */
import { useEffect, useRef, useState, type CSSProperties, type ReactNode, type RefObject } from "react";
import { AgentMark } from "../../home/AppUI";
import { WIN_SIZE } from "../../home/Scenes";

export interface Rect {
  left: number;
  top: number;
  width: number;
  height: number;
}

/**
 * The window's viewport for the app's own CSS: its `vh` / `vw` units read
 * --pz-vh / --pz-vw (scripts/sync-app-css.mjs), so a fixed surface sized in
 * viewport units sizes itself to the scene's window, as the app's does.
 */
const WINDOW_VIEWPORT = {
  "--pz-vh": `${WIN_SIZE.height / 100}px`,
  "--pz-vw": `${WIN_SIZE.width / 100}px`,
} as CSSProperties;

/**
 * The scene window's viewport for `position: fixed` surfaces. In the app they
 * sit in the window's viewport; here a transformed box at the window's top
 * left takes that role, so a surface placed with the app's own coordinates
 * lands where it would in the window, whatever the scene's framing. `cover`
 * spans the whole window (a modal's backdrop fills it); otherwise the layer
 * is a zero-size origin that never takes the canvas's clicks.
 */
export function WindowLayer({
  layerRef,
  cover = false,
  children,
}: {
  layerRef?: RefObject<HTMLDivElement>;
  cover?: boolean;
  children?: ReactNode;
}) {
  return (
    <div
      ref={layerRef}
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        ...(cover ? { right: 0, bottom: 0 } : { width: 0, height: 0 }),
        transform: "translateZ(0)",
        zIndex: 100,
        ...WINDOW_VIEWPORT,
      }}
    >
      {children}
    </div>
  );
}

/**
 * The box of the element `find` picks, in the unscaled pixels of `origin`
 * (a WindowLayer): what the app reads with getBoundingClientRect() in its
 * window. The card scales the scene, so the reading is divided by that scale.
 * It is read again whenever the element or the scene changes size (the
 * scene's fonts loading resize the workspace tabs, for one) and when the
 * scene's markup changes, so an element drawn later is found.
 */
export function useBoxIn(origin: RefObject<HTMLElement>, find: (scene: HTMLElement) => Element | null | undefined): Rect | null {
  const [box, setBox] = useState<Rect | null>(null);
  const findRef = useRef(find);
  useEffect(() => {
    findRef.current = find;
  });
  useEffect(() => {
    const layer = origin.current;
    const scene = layer?.closest<HTMLElement>(".pz");
    if (!layer || !scene) return;
    let observed: Element | null = null;
    const measure = () => {
      const target = findRef.current(scene);
      if (!target) return;
      if (target !== observed) {
        if (observed) observer.unobserve(observed);
        observer.observe(target);
        observed = target;
      }
      const scale = scene.getBoundingClientRect().width / scene.offsetWidth || 1;
      const from = layer.getBoundingClientRect();
      const rect = target.getBoundingClientRect();
      const next = {
        left: (rect.left - from.left) / scale,
        top: (rect.top - from.top) / scale,
        width: rect.width / scale,
        height: rect.height / scale,
      };
      setBox((prev) =>
        prev && ["left", "top", "width", "height"].every((key) => Math.abs(prev[key as keyof Rect] - next[key as keyof Rect]) < 0.5) ? prev : next,
      );
    };
    // A ResizeObserver reports once as soon as it observes, which takes the first reading.
    const observer = new ResizeObserver(() => measure());
    observer.observe(scene);
    // The element may appear later (terminal screens are drawn once in the browser).
    let frame = 0;
    const mutations = new MutationObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(measure);
    });
    mutations.observe(scene, { childList: true, subtree: true });
    let live = true;
    void document.fonts?.ready.then(() => {
      if (live) measure();
    });
    return () => {
      live = false;
      cancelAnimationFrame(frame);
      mutations.disconnect();
      observer.disconnect();
    };
  }, [origin]);
  return box;
}

