/**
 * The app's LiveSessionIcon (src/ui/LiveSessionIcon.tsx) for a Claude Code
 * session: the agent's mark in its tint, titled with what the session's
 * activity reports (sessionIconTooltip in src/sessionMeta.ts).
 */
export function ClaudeSessionIcon() {
  return (
    <span
      title="Effective model: claude-opus-5-5 (Claude Code, reported by the foreground process). Launcher: Claude Code."
      style={{ display: "inline-flex", color: "#D97757" }}
    >
      <AgentMark agent="claude" size={14} />
    </span>
  );
}

